#include "gpu_batch_cublas.cuh"
#include "gpu_batched_matvec.cuh"
#include "gpu_batched_backward.cuh"
#include <cstdio>
int main(){using namespace tao::dual;try{BatchBlas blas;for(int rows:{129,512,16384}){int cols=131,S=4;Vec w(size_t(rows)*cols),x(cols*S),g(rows*S);for(size_t i=0;i<w.size();++i)w[i]=float(int(i%13)-6)*.03f;for(size_t i=0;i<x.size();++i)x[i]=float(int(i%7)-3)*.07f;for(size_t i=0;i<g.size();++i)g[i]=float(int(i%11)-5)*.02f;Device W(w),X(x),G(g),y(rows*S),yr(rows*S),dx(Vec(cols*S,.1f)),dr(Vec(cols*S,.1f)),dw(Vec(size_t(rows)*cols,.2f)),wr(Vec(size_t(rows)*cols,.2f));ds_batched_matvec<<<dim3((rows+3)/4,S),128>>>(W.p,X.p,yr.p,rows,cols,S);ds_batch_dx<<<dim3((cols+31)/32,S),dim3(32,8)>>>(W.p,G.p,dr.p,rows,cols);ds_batch_dw<<<(size_t(rows)*cols+127)/128,128>>>(X.p,G.p,wr.p,rows,cols,S);blas.forward(W.p,X.p,y.p,rows,cols,S);blas.backward(W.p,X.p,G.p,dx.p,dw.p,rows,cols,S);float max=0;auto cmp=[&](Device&a,Device&b){auto aa=a.host(),bb=b.host();for(size_t i=0;i<aa.size();++i){if(!std::isfinite(bb[i]))throw std::runtime_error("nonfinite");max=std::max(max,std::abs(aa[i]-bb[i]));}};cmp(yr,y);cmp(dr,dx);cmp(wr,dw);printf("rows=%d maxabs=%.9g FP32pedantic\n",rows,max);if(max>1e-4)return 1;}return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 2;}}
